-- 89_outdoor_games_prerequisites.sql
-- Adds a "Prerequisites: <value>" line to every Outdoor Games game's
-- prompt (the original 448) -- what skill or prior experience a child
-- needs before attempting the game (e.g. "Comfortable riding a bike
-- independently", "None -- a great first-timer activity"), distinct from
-- "Players:" (group size) and "Materials:" (equipment). Inserted right
-- after "Objective:"/"Players:" and before "Materials:", matching the
-- existing structured-prompt convention that GET /content/outdoor-games
-- (content.py) and the admin Outdoor Games Library screen parse by line
-- prefix.
--
-- Uses REPLACE() targeting the "\n\nMaterials:" anchor (verified present,
-- CHAR(10)+CHAR(10) form, on all 448 rows before running this) rather than
-- rewriting the full prompt text, so every other word/emoji/line in each
-- game is guaranteed untouched -- this only ever touches the exact
-- substring immediately before "Materials:". Guarded with
-- "AND prompt NOT LIKE '%Prerequisites:%'" so re-running this migration
-- is a no-op the second time.

UPDATE dbo.PacketQuestions SET prompt = REPLACE(prompt, CHAR(10)+CHAR(10)+N'Materials:', CHAR(10)+CHAR(10)+N'Prerequisites: None — a great first-timer activity'+CHAR(10)+CHAR(10)+N'Materials:') WHERE question_id = 4018 AND prompt NOT LIKE N'%Prerequisites:%';
UPDATE dbo.PacketQuestions SET prompt = REPLACE(prompt, CHAR(10)+CHAR(10)+N'Materials:', CHAR(10)+CHAR(10)+N'Prerequisites: Comfortable walking or running short distances'+CHAR(10)+CHAR(10)+N'Materials:') WHERE question_id = 4019 AND prompt NOT LIKE N'%Prerequisites:%';
